2	const base=path.dirname(fileURLToPath(import.meta.url)),[label,ref,pageArg='1']=process.argv.slice(2),file=path.resolve(ref??''),relative=path.relative(base,file),page=Number(pageArg),size=1800,sha=b=>crypto.createHash('sha256').update(b).digest('hex');assert(/^[a-z][a-z0-9-]*$/.test(label??''));assert(relative&&!relative.startsWith('..')&&!path.isAbsolute(relative),'Only AC files may be read');assert(Number.isSafeInteger(page)&&page>0);const bytes=fs.readFileSync(file),body=bytes.toString('utf8'),pages=Math.max(1,Math.ceil(body.length/size));assert(page<=pages);const text=body.slice((page-1)*size,page*size),result={file,sha256:sha(bytes),page,pages,total_chars:body.length,from:(page-1)*size,to:Math.min(page*size,body.length),text};assert.equal(sha(fs.readFileSync(file)),result.sha256,'File changed during reading');const output=JSON.stringify(result,null,2)+'\n',folder=path.join(base,'read-pages');fs.mkdirSync(folder,{recursive:true});fs.writeFileSync(path.join(folder,label+'.json'),JSON.stringify({...result,output_sha256:sha(output)},null,2)+'\n',{flag:'wx'});process.stdout.write(output);
